  "loginTitle": "微信登录",
  "loginDescription": "我们使用微信账号标识识别您的账号，保存和同步您的预约记录。头像昵称可稍后完善，预约手机号可授权微信填写，也可以手动填写。",
  "loginHint": "请勾选同意隐私指引后登录。您可以点击下方链接查看完整指引；暂不登录可继续浏览首页和预约时段。",
  "loginConsentText": "我已阅读并同意《用户隐私保护指引》",
  "loginDeclineText": "暂不登录",
  "loginAgreeText": "同意并登录",
  "loginCheckRequired": "请勾选同意《用户隐私保护指引》",
  "privacyTitle": "用户隐私保护",
  "privacyLinkText": "查看《用户隐私保护指引》",
  "privacyPolicyName": "《用户隐私保护指引》",
  "phonePromptTitle": "快捷填写手机号",
  "phonePromptDescription": "授权后，微信手机号会自动填入预约表单，用于到店联系。您也可以手动填写。",
  "phoneManualText": "手动填写",
  "phoneAuthorizeText": "使用微信手机号",
  "reservePrivacyDescription": "获取微信手机号前，请阅读并同意用户隐私保护指引。手机号用于登记预约和到店联系，也可以不授权并手动填写。",
  "profileEditorDescription": "可选择微信头像、填写微信昵称，也可以稍后完善。昵称可预填预约姓名。",
  "profilePrivacyDescription": "完善头像昵称前，请阅读并同意用户隐私保护指引。头像昵称用于个人资料，您可以保留默认资料继续预约。",
  "defaultNickname": "书友",
  "avatarHint": "点击选择头像（最大 2MB）"
}$ui$::jsonb || (CASE WHEN "uiText"->>'loginHint' = '请先查看隐私指引，再勾选同意。暂不登录可继续浏览首页和预约时段。' THEN "uiText" - 'loginHint' ELSE "uiText" END - 'loginReadRequired'),
  "quickDateDays" = CASE WHEN "quickDateDays" = 0 THEN 14 ELSE "quickDateDays" END,
  "bookingAdvanceDays" = CASE WHEN "bookingAdvanceDays" = 0 THEN 90 ELSE "bookingAdvanceDays" END
WHERE "id" = 1;

INSERT INTO "time_slots" ("startTime", "endTime", "maxCapacity", "sortOrder", "isActive")
SELECT seed.* FROM (VALUES
  ('14:00', '15:30', 8, 1, true),
  ('15:30', '17:00', 8, 2, true),
  ('17:00', '18:30', 10, 3, true),
  ('18:30', '20:00', 8, 4, true),
  ('20:00', '21:00', 6, 5, true)
) AS seed("startTime", "endTime", "maxCapacity", "sortOrder", "isActive")
WHERE NOT EXISTS (SELECT 1 FROM "time_slots");

-- Populate previously unconfigured images; preserve uploaded assets.
UPDATE "store_settings" SET "homeHeroImage" = COALESCE("homeHeroImage", $hero$data:image/jpeg;base64,$hero$), "brandLogoImage" = COALESCE("brandLogoImage", $brand$data:image/png;base64,$brand$) WHERE "id" = 1;
